function applyLanguage(lang){
  if(!I18N[lang]) lang = 'en';
  const dict = I18N[lang];
  document.documentElement.lang = lang;
  document.documentElement.dir = LANG_META[lang].dir;

  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key = el.getAttribute('data-i18n');
    if(dict[key] !== undefined) el.textContent = dict[key];
  });
  document.querySelectorAll('[data-i18n-attr]').forEach(el=>{
    const spec = el.getAttribute('data-i18n-attr'); // format: "attr:key"
    const [attr, key] = spec.split(':');
    if(dict[key] !== undefined) el.setAttribute(attr, dict[key]);
  });

  document.querySelectorAll('.lang-select').forEach(sel=>{ sel.value = lang; });
  localStorage.setItem('apex_lang', lang);
}

function initLangSwitcher(){
  const selects = document.querySelectorAll('.lang-select');
  selects.forEach(sel=>{
    sel.innerHTML = Object.keys(LANG_META).map(code=>
      `<option value="${code}">${LANG_META[code].label}</option>`
    ).join('');
    sel.addEventListener('change', e=> applyLanguage(e.target.value));
  });
  const saved = localStorage.getItem('apex_lang');
  applyLanguage(saved && I18N[saved] ? saved : 'en');
}

function initMobileMenu(){
  const btn = document.querySelector('.navbtn-menu');
  const nav = document.querySelector('.navlinks');
  if(!btn || !nav) return;
  btn.addEventListener('click', ()=> nav.classList.toggle('open'));
  nav.querySelectorAll('a').forEach(a=> a.addEventListener('click', ()=> nav.classList.remove('open')));
}

document.addEventListener('DOMContentLoaded', ()=>{
  initLangSwitcher();
  initMobileMenu();
});
